using UnityEngine;
using UnityEngine.Localization.SmartFormat;

namespace Astrea;

[CreateAssetMenu(fileName = "RedemptionFlailOmenData", menuName = "Data/Battle/Omens System/Omen Data/Sothis/RedemptionFlail Omen Data")]
public class RedemptionFlailOmenData : OnEnemyOverCorruptedOmenData
{
	[SerializeField]
	private AfflictionReliefEffect reliefEffect;

	public override string OmenConvertedDescription()
	{
		return GetOverCorruptChantDescription() + Smart.Format(GetOmenRawLocalizedDescription(), ReferenceSingleton<LocalizationManager>.Instance.GetLocalizedThenDecreaseThatEnemyEffect(reliefEffect, 1));
	}
}
